({ calls, defaultText }) => {
  const list = Array.isArray(calls) ? calls : [];
  const call = list.find(item => (item?.function?.name || item?.name) === 'soliumbra_reply') || list[0];
  if (!call) return defaultText ?? '';
  let raw = call?.function?.arguments ?? call?.args ?? call?.arguments ?? '';
  let args = {};
  if (raw && typeof raw === 'object') args = raw;
  else if (typeof raw === 'string') {
    try { args = JSON.parse(raw); } catch (error) {
      const pick = key => {
        const match = raw.match(new RegExp('"' + key + '"\\s*:\\s*"((?:\\\\.|[^"\\\\])*)'));
        if (!match) return '';
        try { return JSON.parse('"' + match[1] + '"'); } catch (inner) { return match[1]; }
      };
      args = { think_nya: pick('think_nya'), game_content: pick('game_content') };
    }
  }
  const think = args.think_nya ? `<xzs_plan>\n${args.think_nya}\n</xzs_plan>\n` : '';
